const Anthropic = require('@anthropic-ai/sdk');
const { getPersonality } = require('./personalities');

class ClippyAI {
  constructor(opts = {}) {
    this.client = new Anthropic();
    this.personalityKey = opts.personality || 'clippy';
    this.conversationHistory = [];
    this.maxHistory = 20; // Keep last 20 exchanges
  }

  setPersonality(key) {
    this.personalityKey = key;
    // Clear history on personality switch so the new persona starts fresh
    this.conversationHistory = [];
  }

  async checkIn(activitySummary) {
    const personality = getPersonality(this.personalityKey);

    const userMessage = `Here's what the user has been doing on their computer:\n\n${activitySummary}\n\nGive a brief check-in comment based on this activity. If nothing interesting is happening, you can say something idle or skip with just "[skip]". Keep it to 1-2 sentences max.`;

    this.conversationHistory.push({
      role: 'user',
      content: userMessage,
    });

    // Trim history
    if (this.conversationHistory.length > this.maxHistory) {
      this.conversationHistory = this.conversationHistory.slice(-this.maxHistory);
    }

    try {
      const response = await this.client.messages.create({
        model: 'claude-haiku-4-5-20251001',
        max_tokens: 150,
        system: personality.system,
        messages: this.conversationHistory,
      });

      const text = response.content[0]?.text || '';

      this.conversationHistory.push({
        role: 'assistant',
        content: text,
      });

      // If the AI says skip, return null
      if (text.trim() === '[skip]' || text.includes('[skip]')) {
        return null;
      }

      return text.trim();
    } catch (err) {
      console.error('AI check-in error:', err.message);
      return null;
    }
  }
}

module.exports = { ClippyAI };

