const { contextBridge, ipcRenderer } = require('electron');

contextBridge.exposeInMainWorld('clippy', {
  onMessage: (callback) => ipcRenderer.on('clippy-message', (_, msg) => callback(msg)),
  onPersonalityChanged: (callback) => ipcRenderer.on('personality-changed', (_, p) => callback(p)),
  dismiss: () => ipcRenderer.send('dismiss'),
  getPersonality: () => ipcRenderer.invoke('get-personality'),
});

