* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  background: transparent;
  overflow: hidden;
  font-family: -apple-system, BlinkMacSystemFont, 'SF Pro Rounded', 'Helvetica Neue', sans-serif;
  -webkit-app-region: drag;
  user-select: none;
}

#container {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-end;
  width: 320px;
  height: 200px;
  position: relative;
}

/* Speech bubble */
#bubble {
  background: rgba(30, 30, 30, 0.92);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 16px;
  padding: 12px 16px;
  max-width: 280px;
  color: #f0f0f0;
  font-size: 13px;
  line-height: 1.5;
  position: absolute;
  bottom: 70px;
  animation: bubble-in 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
  -webkit-app-region: no-drag;
  cursor: pointer;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
}

#bubble.hidden {
  display: none;
}

#bubble-tail {
  position: absolute;
  bottom: -8px;
  left: 50%;
  transform: translateX(-50%);
  width: 0;
  height: 0;
  border-left: 8px solid transparent;
  border-right: 8px solid transparent;
  border-top: 8px solid rgba(30, 30, 30, 0.92);
}

/* Clippy character */
#clippy {
  width: 56px;
  height: 56px;
  background: rgba(30, 30, 30, 0.85);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  -webkit-app-region: no-drag;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.3);
  position: absolute;
  bottom: 4px;
}

#clippy:hover {
  transform: scale(1.1);
  box-shadow: 0 6px 24px rgba(0, 0, 0, 0.4);
}

#clippy:active {
  transform: scale(0.95);
}

#clippy-emoji {
  font-size: 28px;
  line-height: 1;
}

/* Animations */
@keyframes bubble-in {
  from {
    opacity: 0;
    transform: translateY(8px) scale(0.9);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@keyframes bubble-out {
  from {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
  to {
    opacity: 0;
    transform: translateY(8px) scale(0.9);
  }
}

#bubble.dismissing {
  animation: bubble-out 0.2s ease-out forwards;
}

/* Idle bounce animation */
@keyframes idle-bounce {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-4px); }
}

#clippy.idle {
  animation: idle-bounce 3s ease-in-out infinite;
}

