const bubble = document.getElementById('bubble');
const bubbleText = document.getElementById('bubble-text');
const clippy = document.getElementById('clippy');
const clippyEmoji = document.getElementById('clippy-emoji');

let dismissTimer = null;

function showMessage(text) {
  // Clear any pending dismiss
  if (dismissTimer) clearTimeout(dismissTimer);

  bubbleText.textContent = text;
  bubble.classList.remove('hidden', 'dismissing');
  clippy.classList.remove('idle');

  // Auto-dismiss after 10 seconds
  dismissTimer = setTimeout(() => dismissBubble(), 10000);
}

function dismissBubble() {
  if (bubble.classList.contains('hidden')) return;
  bubble.classList.add('dismissing');
  setTimeout(() => {
    bubble.classList.add('hidden');
    bubble.classList.remove('dismissing');
    clippy.classList.add('idle');
  }, 200);
}

// Click bubble to dismiss
bubble.addEventListener('click', () => {
  dismissBubble();
  window.clippy.dismiss();
});

// Click clippy to dismiss current message
clippy.addEventListener('click', () => {
  if (!bubble.classList.contains('hidden')) {
    dismissBubble();
    window.clippy.dismiss();
  }
});

// Listen for messages from main process
window.clippy.onMessage((msg) => {
  showMessage(msg);
});

// Listen for personality changes
window.clippy.onPersonalityChanged((personality) => {
  clippyEmoji.textContent = personality.emoji;
});

// Initialize
(async () => {
  const personality = await window.clippy.getPersonality();
  if (personality) {
    clippyEmoji.textContent = personality.emoji;
  }
  clippy.classList.add('idle');
})();

