const { app, BrowserWindow, Tray, Menu, nativeImage, ipcMain, screen } = require('electron');
const path = require('path');
const Store = require('electron-store').default;
const { WindowMonitor } = require('./src/monitor');
const { ClippyAI } = require('./src/ai');
const { listPersonalities, getPersonality } = require('./src/personalities');

const store = new Store({
  defaults: {
    personality: 'clippy',
    checkInInterval: 120000, // 2 minutes
    paused: false,
  },
});

let win = null;
let tray = null;
let monitor = null;
let ai = null;
let checkInTimer = null;

function createWindow() {
  const { width: screenWidth, height: screenHeight } = screen.getPrimaryDisplay().workAreaSize;

  win = new BrowserWindow({
    width: 320,
    height: 200,
    x: screenWidth - 340,
    y: screenHeight - 220,
    frame: false,
    transparent: true,
    alwaysOnTop: true,
    hasShadow: false,
    resizable: false,
    skipTaskbar: true,
    focusable: false,
    webPreferences: {
      preload: path.join(__dirname, 'preload.js'),
      contextIsolation: true,
      nodeIntegration: false,
    },
  });

  win.setVisibleOnAllWorkspaces(true, { visibleOnFullScreen: true });
  win.setIgnoreMouseEvents(false);
  // Make click-through except for the clippy/bubble areas
  // (handled by -webkit-app-region in CSS)

  win.loadFile(path.join(__dirname, 'renderer', 'index.html'));
}

function createTray() {
  // Create a simple tray icon (📎 emoji rendered as image)
  const iconSize = 18;
  const canvas = `<svg xmlns="http://www.w3.org/2000/svg" width="${iconSize}" height="${iconSize}" viewBox="0 0 100 100"><text y=".9em" font-size="85">📎</text></svg>`;
  const icon = nativeImage.createFromBuffer(
    Buffer.from(canvas),
    { width: iconSize, height: iconSize }
  );
  // Fallback: use a simple template icon
  tray = new Tray(nativeImage.createEmpty());
  tray.setTitle('📎');

  updateTrayMenu();
}

function updateTrayMenu() {
  const currentKey = store.get('personality');
  const paused = store.get('paused');
  const interval = store.get('checkInInterval');

  const personalityItems = listPersonalities().map((p) => ({
    label: `${p.emoji} ${p.name}`,
    type: 'radio',
    checked: p.key === currentKey,
    click: () => {
      store.set('personality', p.key);
      ai.setPersonality(p.key);
      const personality = getPersonality(p.key);
      win?.webContents.send('personality-changed', {
