    {
      label: 'Quit',
      click: () => app.quit(),
    },
  ]);

  tray.setContextMenu(menu);
}

async function doCheckIn() {
  if (!monitor || !ai) return;

  const summary = monitor.getSummary();
  const message = await ai.checkIn(summary);

  if (message) {
    win?.webContents.send('clippy-message', message);
  }
}

function startCheckIns() {
  stopCheckIns();
  const interval = store.get('checkInInterval');
  checkInTimer = setInterval(() => doCheckIn(), interval);
  // Do an initial check-in after a short delay
  setTimeout(() => doCheckIn(), 5000);
}

function stopCheckIns() {
  if (checkInTimer) {
    clearInterval(checkInTimer);
    checkInTimer = null;
  }
}

function restartCheckInTimer() {
  if (!store.get('paused')) {
    startCheckIns();
  }
}

// IPC handlers
ipcMain.on('dismiss', () => {
  // Could track dismissals to reduce frequency
});

ipcMain.handle('get-personality', () => {
