const { EventEmitter } = require('events');

class WindowMonitor extends EventEmitter {
  constructor(opts = {}) {
    super();
    this.pollInterval = opts.pollInterval || 3000;
    this.historyLimit = opts.historyLimit || 100; // ~5 min at 3s intervals
    this.history = []; // { app, title, timestamp }
    this.current = null;
    this.timer = null;
  }

  async poll() {
    try {
      // active-win is ESM-only, dynamic import
      const { activeWindow } = await import('active-win');
      const win = await activeWindow();
      if (!win) return;

      const entry = {
        app: win.owner?.name || 'Unknown',
        title: win.title || '',
        timestamp: Date.now(),
      };

      // Detect change
      const changed =
        !this.current ||
        this.current.app !== entry.app ||
        this.current.title !== entry.title;

      this.current = entry;
      this.history.push(entry);

      // Trim history
      if (this.history.length > this.historyLimit) {
        this.history = this.history.slice(-this.historyLimit);
      }

      if (changed) {
        this.emit('window-change', entry);
      }
    } catch (err) {
      // Silently continue — screen recording permission may not be granted yet
      console.error('Monitor poll error:', err.message);
    }
  }

  start() {
    this.poll();
    this.timer = setInterval(() => this.poll(), this.pollInterval);
  }

  stop() {
    if (this.timer) {
      clearInterval(this.timer);
      this.timer = null;
    }
  }

  /** Build a summary of recent activity for the AI */
  getSummary() {
    if (this.history.length === 0) return 'No activity recorded yet.';

    // Group consecutive entries by app
    const segments = [];
