const { app, BrowserWindow, Tray, Menu, nativeImage, ipcMain, screen, dialog } = require('electron');
const path = require('path');
const fs = require('fs');
const { WindowMonitor } = require('./src/monitor');
const { ClippyAI } = require('./src/ai');
const { listPersonalities, getPersonality } = require('./src/personalities');

// Simple JSON settings store
const settingsPath = path.join(app.getPath('userData'), 'settings.json');
const defaults = { personality: 'clippy', checkInInterval: 120000, paused: false, apiKey: '' };

function loadSettings() {
  try {
    return { ...defaults, ...JSON.parse(fs.readFileSync(settingsPath, 'utf8')) };
  } catch {
    return { ...defaults };
  }
}

function saveSettings(s) {
  fs.writeFileSync(settingsPath, JSON.stringify(s, null, 2));
}

let settings = loadSettings();
let win = null;
let tray = null;
let monitor = null;
let ai = null;
let checkInTimer = null;

function createWindow() {
  const { width: screenWidth, height: screenHeight } = screen.getPrimaryDisplay().workAreaSize;

  win = new BrowserWindow({
    width: 320,
    height: 200,
    x: screenWidth - 340,
    y: screenHeight - 220,
    frame: false,
    transparent: true,
    alwaysOnTop: true,
    hasShadow: false,
    resizable: false,
    skipTaskbar: true,
    focusable: false,
    webPreferences: {
      preload: path.join(__dirname, 'preload.js'),
      contextIsolation: true,
      nodeIntegration: false,
    },
  });

  win.setVisibleOnAllWorkspaces(true, { visibleOnFullScreen: true });
  win.loadFile(path.join(__dirname, 'renderer', 'index.html'));
}

function createTray() {
  tray = new Tray(nativeImage.createEmpty());
  tray.setTitle('📎');
  updateTrayMenu();
}

function updateTrayMenu() {
  const hasKey = !!settings.apiKey;

  const personalityItems = listPersonalities().map((p) => ({
    label: `${p.emoji} ${p.name}`,
    type: 'radio',
    checked: p.key === settings.personality,
    click: () => {
      settings.personality = p.key;
      saveSettings(settings);
      ai.setPersonality(p.key);
      const personality = getPersonality(p.key);
      win?.webContents.send('personality-changed', {
        emoji: personality.emoji,
        name: personality.name,
      });
      updateTrayMenu();
    },
  }));

  const intervalItems = [
    { label: '30 seconds', value: 30000 },
    { label: '1 minute', value: 60000 },
    { label: '2 minutes', value: 120000 },
    { label: '5 minutes', value: 300000 },
  ].map((item) => ({
    label: item.label,
    type: 'radio',
    checked: settings.checkInInterval === item.value,
    click: () => {
      settings.checkInInterval = item.value;
      saveSettings(settings);
      restartCheckInTimer();
      updateTrayMenu();
    },
  }));

  const menu = Menu.buildFromTemplate([
    { label: hasKey ? 'Clippy' : 'Clippy (no API key)', enabled: false },
    { type: 'separator' },
    {
      label: hasKey ? 'Change API Key...' : 'Set API Key...',
      click: () => promptForApiKey(),
    },
    { type: 'separator' },
    { label: 'Personality', submenu: personalityItems },
    { label: 'Check-in Frequency', submenu: intervalItems },
    { type: 'separator' },
    {
      label: settings.paused ? '▶ Resume' : '⏸ Pause',
      click: () => {
        settings.paused = !settings.paused;
        saveSettings(settings);
        if (settings.paused) stopCheckIns();
        else startCheckIns();
        updateTrayMenu();
      },
    },
    { label: 'Check In Now', click: () => doCheckIn(), enabled: hasKey },
    { type: 'separator' },
    { label: 'Quit', click: () => app.quit() },
  ]);

  tray.setContextMenu(menu);
}

async function promptForApiKey() {
  // Create a small prompt window
  const promptWin = new BrowserWindow({
    width: 480,
    height: 180,
    frame: true,
    resizable: false,
    minimizable: false,
    maximizable: false,
    alwaysOnTop: true,
    title: 'Clippy — API Key',
    webPreferences: { contextIsolation: true, preload: path.join(__dirname, 'preload-prompt.js') },
  });

  promptWin.loadFile(path.join(__dirname, 'renderer', 'prompt.html'));

  return new Promise((resolve) => {
    ipcMain.once('api-key-submit', (_, key) => {
      if (key && key.startsWith('sk-')) {
        settings.apiKey = key;
        saveSettings(settings);
        ai.setApiKey(key);
        updateTrayMenu();
        win?.webContents.send('clippy-message', "I'm alive! Let me watch what you're up to...");
        if (!settings.paused) startCheckIns();
      }
      promptWin.close();
      resolve();
    });

    promptWin.on('closed', () => resolve());
  });
}

async function doCheckIn() {
  if (!monitor || !ai || !settings.apiKey) return;
  const summary = monitor.getSummary();
  const message = await ai.checkIn(summary);
  if (message) {
    win?.webContents.send('clippy-message', message);
  }
}

function startCheckIns() {
  stopCheckIns();
  if (!settings.apiKey) return;
  checkInTimer = setInterval(() => doCheckIn(), settings.checkInInterval);
  setTimeout(() => doCheckIn(), 5000);
}

function stopCheckIns() {
  if (checkInTimer) {
    clearInterval(checkInTimer);
    checkInTimer = null;
  }
}

function restartCheckInTimer() {
  if (!settings.paused) startCheckIns();
}

// IPC
ipcMain.on('dismiss', () => {});
ipcMain.handle('get-personality', () => {
  const p = getPersonality(settings.personality);
  return { emoji: p.emoji, name: p.name };
});

// App lifecycle
app.whenReady().then(() => {
  monitor = new WindowMonitor();
  ai = new ClippyAI({ personality: settings.personality, apiKey: settings.apiKey || undefined });

  createWindow();
  createTray();
  monitor.start();

  if (settings.apiKey && !settings.paused) {
    startCheckIns();
  } else if (!settings.apiKey) {
    // Show a message asking for API key
    setTimeout(() => {
      win?.webContents.send('clippy-message', 'Click the 📎 in the menu bar and set your Anthropic API key to get started!');
    }, 2000);
  }

  console.log('📎 Clippy is running!');
});

app.on('window-all-closed', (e) => e.preventDefault());

app.on('before-quit', () => {
  monitor?.stop();
  stopCheckIns();
});

