const { EventEmitter } = require('events');
const { execFile } = require('child_process');

class WindowMonitor extends EventEmitter {
  constructor(opts = {}) {
    super();
    this.pollInterval = opts.pollInterval || 3000;
    this.historyLimit = opts.historyLimit || 100;
    this.history = [];
    this.current = null;
    this.timer = null;
  }

  getActiveWindow() {
    return new Promise((resolve) => {
      const script = `
        tell application "System Events"
          set frontApp to name of first application process whose frontmost is true
        end tell
        tell application frontApp
          try
            set winTitle to name of front window
          on error
            set winTitle to ""
          end try
        end tell
        return frontApp & "|||" & winTitle
      `;

      execFile('osascript', ['-e', script], { timeout: 3000 }, (err, stdout) => {
        if (err) {
          resolve(null);
          return;
        }
        const parts = stdout.trim().split('|||');
        resolve({
          app: parts[0] || 'Unknown',
          title: parts[1] || '',
        });
      });
    });
  }

  async poll() {
    try {
      const win = await this.getActiveWindow();
      if (!win) return;

      const entry = {
        app: win.app,
        title: win.title,
        timestamp: Date.now(),
      };

      const changed =
        !this.current ||
        this.current.app !== entry.app ||
        this.current.title !== entry.title;

      this.current = entry;
      this.history.push(entry);

      if (this.history.length > this.historyLimit) {
        this.history = this.history.slice(-this.historyLimit);
      }

      if (changed) {
        this.emit('window-change', entry);
      }
    } catch (err) {
      console.error('Monitor poll error:', err.message);
    }
  }

  start() {
    this.poll();
    this.timer = setInterval(() => this.poll(), this.pollInterval);
  }

  stop() {
    if (this.timer) {
      clearInterval(this.timer);
      this.timer = null;
    }
  }

  getSummary() {
    if (this.history.length === 0) return 'No activity recorded yet.';

    const segments = [];
    let seg = null;

    for (let i = 0; i < this.history.length; i++) {
      const entry = this.history[i];
      if (!seg || seg.app !== entry.app) {
        if (seg) seg.endTime = this.history[i - 1]?.timestamp || seg.startTime;
        seg = {
          app: entry.app,
          titles: new Set([entry.title]),
          startTime: entry.timestamp,
          endTime: entry.timestamp,
        };
        segments.push(seg);
      } else {
        seg.titles.add(entry.title);
        seg.endTime = entry.timestamp;
      }
    }

    const now = Date.now();
    const lines = segments.slice(-10).map((s) => {
      const duration = Math.round((s.endTime - s.startTime) / 1000);
      const ago = Math.round((now - s.endTime) / 1000);
      const titles = [...s.titles].filter(Boolean).slice(0, 3).join(', ');
      const durationStr = duration > 60 ? `${Math.round(duration / 60)}m` : `${duration}s`;
      const agoStr = ago > 10 ? `, ${Math.round(ago / 60)}m ago` : ', now';
      return `- ${s.app} (${durationStr}${agoStr})${titles ? ': ' + titles : ''}`;
    });

    const currentLine = this.current
      ? `\nCurrently active: ${this.current.app} — "${this.current.title}"`
      : '';

    return `Recent activity:\n${lines.join('\n')}${currentLine}`;
  }
}

module.exports = { WindowMonitor };

