          "Listen to the same song on repeat until it loses all meaning.",
          "Queue up 3 hours of sea shanties. Trust the process.",
        ],
      },
      {
        match: (app) => /figma|sketch|photoshop/i.test(app),
        lines: [
          "Make everything Comic Sans. The client will LOVE it.",
          "What if every color was slightly different? Chaos rainbow.",
          "Add a hidden easter egg the client will never find.",
        ],
      },
      {
        match: () => true,
        lines: [
          "Hey. HEY. Open a new browser tab. You know you want to.",
          "When was the last time you rearranged your desktop icons? DO IT NOW.",
          "Change your wallpaper to something chaotic. Set the tone.",
          "You should start a side project. Right now. Abandon this one.",
          "REORGANIZE YOUR DOCK. This is critical and urgent.",
        ],
      },
    ],
  },
};

function getPrompt(personalityKey, app, title) {
  const personality = prompts[personalityKey] || prompts.clippy;
  const matched = personality.patterns.find((p) => p.match(app, title));
  const lines = matched ? matched.lines : personality.patterns.at(-1).lines;
  return lines[Math.floor(Math.random() * lines.length)];
}

function getPersonality(key) {
  const p = prompts[key] || prompts.clippy;
  return { name: p.name, emoji: p.emoji };
}

function listPersonalities() {
  return Object.entries(prompts).map(([key, p]) => ({
    key,
    name: p.name,
    emoji: p.emoji,
  }));
}

module.exports = { getPrompt, getPersonality, listPersonalities };

